class Solution {
    public int minMaxDifference(int num){
        String digits=String.valueOf(num);
        char source='9';
        for(char character:digits.toCharArray())if(character!='9'){
            source=character;
            break;
        }
        int maximum=Integer.parseInt(digits.replace(source,'9'));
        int minimum=Integer.parseInt(digits.replace(digits.charAt(0),'0'));
        return maximum-minimum;
    }
}

code.kotlin:
class Solution {
    fun minMaxDifference(num:Int):Int{
        val digits=num.toString();
        val source=digits.firstOrNull{
            it!='9'
        }?:'9';
        val maximum=digits.replace(source,'9').toInt();
        val minimum=digits.replace(digits[0],'0').toInt();
        return maximum-minimum
    }
}

